/*
 * Shared writing topics and article metadata contract.
 * Article records will be generated by the MDX content loader rather than
 * being manually maintained in this file.
 */

export const writingTopics = [
  "Backend Engineering",
  "Computer Science",
  "Competitive Programming",
  "Engineering Notes",
  "Projects & Architecture",
] as const;

export type WritingTopic = (typeof writingTopics)[number];

export interface WritingArticle {
  slug: string;
  title: string;
  description: string;
  date: string;
  category: WritingTopic;
  tags: string[];
  readingTime: number;
  published: boolean;
  featured?: boolean;
  coverImage?: string;
}

/*
 * The article body is kept separately from its metadata so the listing
 * page doesn't need to load and render the full MDX content.
 */
export interface WritingArticleDocument extends WritingArticle {
  content: string;
}
